export const PLUG_R=6.35,SHEAR=6.35,FLOOR=-0.8,BLADE_TOP=3.01,BLADE_BOT=-5.5,CAP_Z=21,BODY_LEN=28.5,PIN_R=1.46;
export const PIN_X=[5.87,9.84,13.81,17.78,21.75];
export const KEY_PIN=[4.102,5.245,4.483,6.007,4.864];
export const DRIVER=[4.19,4.19,4.19,4.19,4.19];
export const KEY_TIP=27,TRAVEL=28.6,FLAT=0.395,SLOPE=0.8390996312,TURN_MAX=90;
export const KEYS={correta:KEY_PIN.map(l=>+(SHEAR-l).toFixed(3)),errada:[2.248,1.105,1.867,2.629,1.486]};
export function keyTopLocal(c,s){if(s<0||s>KEY_TIP)return null;let t=BLADE_TOP;for(let i=0;i<5;i++)t=Math.min(t,c[i]+Math.max(0,Math.abs(s-PIN_X[i])-FLAT)*SLOPE);t=Math.min(t,FLOOR+(KEY_TIP-s)*SLOPE);return Math.max(FLOOR,t);}
export function shoulderX(insert){return -(1-insert/100)*TRAVEL;}
export function keyProfile(key,n=120){if(!key)return[];const c=KEYS[key],o=[];for(let j=0;j<=n;j++){const s=KEY_TIP*j/n;o.push([s,keyTopLocal(c,s)]);}return o;}
export function createState(){return{key:null,insert:0,angle:0,target:0,cutaway:true,msg:'Sem chave. Os contrapinos cruzam a linha de cisalhamento e travam o miolo.',tone:'info'};}
export function pose(s){const sh=shoulderX(s.insert),c=s.key?KEYS[s.key]:null,rotated=s.angle>0.01;const pins=PIN_X.map((x,i)=>{let b=FLOOR,touch=false;if(c){const t=keyTopLocal(c,x-sh);if(t!==null){b=Math.max(FLOOR,t);touch=true;}}const kTop=b+KEY_PIN[i];const dBot=rotated?SHEAR:kTop;const dTop=dBot+DRIVER[i];return{x,keyPin:{z0:b,z1:kTop,len:KEY_PIN[i]},driver:{z0:dBot,z1:dTop,len:DRIVER[i]},spring:{z0:dTop,z1:CAP_Z,len:CAP_Z-dTop},contactZ:b,touching:touch,aligned:Math.abs(kTop-SHEAR)<0.02};});return{shear:SHEAR,plugR:PLUG_R,bodyLen:BODY_LEN,capZ:CAP_Z,pinR:PIN_R,floor:FLOOR,angle:s.angle,angleRad:s.angle*Math.PI/180,turnMax:TURN_MAX,key:s.key?{name:s.key,shoulderX:sh,tipX:sh+KEY_TIP,bladeBot:BLADE_BOT,bladeTop:BLADE_TOP,profile:keyProfile(s.key)}:null,pins};}
export function aligned(s){return pose(s).pins.map(p=>p.aligned);}
export function canTurn(s){return !!s.key&&s.insert>=100&&aligned(s).every(Boolean);}
export function isRotated(s){return s.target>0||s.angle>0.01;}
export function summary(s){const a=aligned(s);return{pins:a.filter(Boolean).length,aligned:a,rotated:isRotated(s),open:s.angle>=TURN_MAX-0.01,free:canTurn(s)};}
export function transition(s,a){const n={...s},rot=isRotated(s);switch(a.type){case'key':if(rot){n.msg='Bloqueado: retorne o miolo antes de trocar a chave.';n.tone='block';return n;}n.key=a.key;n.insert=0;n.msg='Chave '+a.key+' selecionada. Insira gradualmente.';n.tone='info';return n;case'remove':if(rot){n.msg='Bloqueado: o miolo girado prende a chave.';n.tone='block';return n;}return{...createState(),cutaway:s.cutaway};case'insert':{if(!s.key){n.msg='Selecione uma chave primeiro.';n.tone='block';return n;}if(rot){n.msg='Bloqueado: o miolo girado prende a chave.';n.tone='block';return n;}const v=Math.max(0,Math.min(100,Math.round(Number(a.value)||0)));n.insert=v;n.msg='Inserção '+v+'%. Pinos alinhados: '+aligned(n).filter(Boolean).length+'/5.';n.tone='info';return n;}case'turn':{if(canTurn(s)){n.target=TURN_MAX;n.msg='Aberto: todas as divisões estão na linha de cisalhamento; o miolo gira.';n.tone='ok';return n;}const k=aligned(s).filter(Boolean).length;n.msg=!s.key?'Bloqueado: sem chave, os contrapinos travam o miolo.':s.insert<100?'Bloqueado: chave parcialmente inserida ('+k+'/5 alinhados).':'Bloqueado: perfil incorreto ('+k+'/5 alinhados).';n.tone='block';return n;}case'return':if(!rot)return s;n.target=0;n.msg='Miolo retornando à posição inicial.';n.tone='info';return n;case'tick':{const step=a.instant?1e9:Math.max(0,a.dt||0)*180,d=s.target-s.angle;if(d===0)return s;n.angle=Math.abs(d)<=step?s.target:s.angle+Math.sign(d)*step;if(n.angle===0&&s.target===0){n.msg='Miolo na posição inicial. A chave pode ser retirada.';n.tone='info';}return n;}case'cutaway':n.cutaway=!s.cutaway;return n;case'reset':return createState();default:return s;}}

// Geometry adapted from Nader / Anatomy Community, MIT; see the artifact notices.
// The lock model, in millimetres: one source for the build, the live page and the sound events.
// A 5-pin cylinder with Schlage-like numbers: plug 12.7 mm (0.500"), pins 2.92 mm (0.115"), first pin 5.87 mm (0.231")
// behind the key shoulder, pins 3.97 mm (0.156") apart, cut depths in 0.381 mm (0.015") steps, 100° cuts with a
// 0.79 mm (0.031") flat, driver pins 4.19 mm (0.165"). The plug stands upright: the key comes down from above,
// pins lie along +x, the housing is cut open on the plane y = 0 and its front half (y > 0) removed.
export const LK = {
  R: 6.35, PIN_R: 1.46, RH: 9, TOWER: 21, TOWER_Y: 4, ZTOP: 28.5, LIP_R: 7.6, FACE: 29.7,
  S0: 5.87, PITCH: 3.97, STEP: 0.381, CUT_FLAT: 0.395, FLANK: 1 / Math.tan((50 * Math.PI) / 180),
  SPINE: -5.5, BLADE: 8.51, KEY_T: 1.05, KEYWAY: [-5.65, 3.5], KEYWAY_Y: 1.15,
  REST: -0.8, DRIVER: 4.19, COVER: 21, CAM_L: 10, OUT: 28.6, TIP: 27.0,
  RIGHT: [2, 5, 3, 7, 4], WRONG: [2, 5, 3, 1, 4],
};
LK.DEPTH0 = LK.SPINE + LK.BLADE;
LK.Z = [0, 1, 2, 3, 4].map((n) => LK.FACE - LK.S0 - LK.PITCH * n);
LK.KEYPIN = LK.RIGHT.map((d) => LK.R - (LK.DEPTH0 - LK.STEP * d));

// Bitting edge of a key (x across the blade) at distance s from its shoulder; -Infinity past the tip.
export function lkProfile(bitting, s) {
  const { S0, PITCH, STEP, CUT_FLAT, FLANK, DEPTH0, TIP } = LK;
  if (s < 0 || s > TIP) return -Infinity;
  let x = DEPTH0;
  bitting.forEach((d, n) => { x = Math.min(x, DEPTH0 - STEP * d + Math.max(0, Math.abs(s - (S0 + PITCH * n)) - CUT_FLAT) * FLANK); });
  const ramp = S0 + PITCH * 4 + 1.9;
  if (s > ramp) x = Math.min(x, DEPTH0 - (s - ramp) * 1.15);
  return x;
}
// The key outline in its own plane: [x across, s along] points, shoulder at s = 0, bow at s < 0.
export function lkOutline(bitting, round = true) {
  const { DEPTH0, SPINE, TIP } = LK;
  const pts = [];
  const NS = Math.round(TIP / 0.05);
  for (let i = 0; i <= NS; i++) { const s = Math.min(TIP, i * 0.05); pts.push([lkProfile(bitting, s), s]); }
  const simple = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    const a = simple[simple.length - 1], b = pts[i], c = pts[i + 1];
    const cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    if (Math.abs(cross) > 1e-4) simple.push(b);
  }
  simple.push(pts[pts.length - 1]);
  const hiX = DEPTH0 + 1.4, loX = SPINE - 0.9;
  const bow = [];
  let hole;
  if (round) {
    const cx = -1, cs = -14.5, r = 10;
    const a0 = Math.atan2(Math.sqrt(r * r - (hiX - cx) ** 2), hiX - cx), a1 = Math.atan2(Math.sqrt(r * r - (loX - cx) ** 2), loX - cx) - 2 * Math.PI;
    for (let i = 0; i <= 40; i++) { const a = a0 + ((a1 - a0) * i) / 40; bow.push([cx + r * Math.cos(a), cs + r * Math.sin(a)]); }
    hole = Array.from({ length: 24 }, (_, i) => [cx + 2.3 * Math.cos((i / 24) * 2 * Math.PI), cs - 5 + 2.3 * Math.sin((i / 24) * 2 * Math.PI)]);
  } else {
    const x0 = -12.4, x1 = 10.6, s0 = -22.5, s1 = -5.2, r = 3.2;
    const corner = (cx, cs, from) => Array.from({ length: 7 }, (_, i) => { const a = from - (Math.PI / 2) * (i / 6); return [cx + r * Math.cos(a), cs + r * Math.sin(a)]; });
    bow.push([hiX, s1], ...corner(x1 - r, s1 - r, Math.PI / 2), ...corner(x1 - r, s0 + r, 0), ...corner(x0 + r, s0 + r, -Math.PI / 2), ...corner(x0 + r, s1 - r, -Math.PI), [loX, s1]);
    hole = Array.from({ length: 24 }, (_, i) => [x0 + 4.4 + 2.0 * Math.cos((i / 24) * 2 * Math.PI), s0 + 4.4 + 2.0 * Math.sin((i / 24) * 2 * Math.PI)]);
  }
  const ring = [[hiX, 0], ...bow, [loX, 0], [SPINE, 0], [SPINE, TIP - 1.2], [SPINE + 1.6, TIP], ...simple.reverse()];
  return { ring, hole, hiX, loX, neck: bow[0][1] };
}

