import { createState, transition, summary, isRotated, TURN_MAX } from './model.mjs';
import { render } from './geometry.mjs';

export function mount(root, env = {}) {
  let state = createState();
  let theme = env.theme === 'dark' ? 'dark' : 'light';
  let reduced = !!env.reducedMotion;
  let visible = true;
  let raf = 0, last = 0, lastSvg = '';

  root.classList.add('fx-root');
  root.innerHTML =
    '<div class="fx-stage" id="fx-stage"></div>' +
    '<ul class="fx-legend" aria-label="Legenda"><li><i style="background:#5f656d"></i>Carcaça fixa em corte (aço)</li><li><i style="background:#d6a64a"></i>Chave e pinos inferiores (latão)</li><li><i style="background:#c6cbd1"></i>Contrapinos e molas (fixos)</li><li><i style="background:#2f9d5f"></i>Linha de cisalhamento: verde quando alinhada</li></ul>' +
    '<div class="fx-status" id="fx-status" role="status" aria-live="polite"></div>' +
    '<div class="fx-pins" id="fx-pins"></div>' +
    '<div class="fx-controls" role="group" aria-label="Controles da fechadura">' +
    '<button type="button" id="fx-key-right" aria-pressed="false">Chave correta</button>' +
    '<button type="button" id="fx-key-wrong" aria-pressed="false">Chave errada</button>' +
    '<button type="button" id="fx-remove">Retirar chave</button>' +
    '<label for="fx-insert">Inserção <input type="range" id="fx-insert" min="0" max="100" step="1" value="0" aria-valuetext="0%"></label>' +
    '<button type="button" id="fx-turn">Girar</button>' +
    '<button type="button" id="fx-return">Retornar</button>' +
    '<button type="button" id="fx-cut" aria-pressed="true">Corte</button>' +
    '<button type="button" id="fx-reset">Reiniciar</button>' +
    '</div>';

  const $ = id => root.querySelector('#' + id);
  const stage = $('fx-stage'), status = $('fx-status'), pinsEl = $('fx-pins');
  const bRight = $('fx-key-right'), bWrong = $('fx-key-wrong'), bRemove = $('fx-remove');
  const range = $('fx-insert'), bTurn = $('fx-turn'), bRet = $('fx-return'), bCut = $('fx-cut'), bReset = $('fx-reset');

  function draw() {
    const svg = render(state, { theme });
    if (svg !== lastSvg) { stage.innerHTML = svg; lastSvg = svg; }
  }

  function ui() {
    const s = summary(state), rot = isRotated(state);
    status.textContent = state.msg;
    status.dataset.tone = state.tone;
    pinsEl.textContent = 'Pinos alinhados: ' + s.pins + '/5 [' + s.aligned.map(a => a ? '✓' : '✗').join(' ') +
      '] · Giro: ' + Math.round(state.angle) + '° de ' + TURN_MAX + '° · ' +
      (state.key ? 'Chave ' + state.key + ', inserção ' + state.insert + '%' : 'Sem chave') + ' · Ferrolho: ' + (10*Math.sin(state.angle*Math.PI/180)).toFixed(1) + ' mm';
    bRight.setAttribute('aria-pressed', String(state.key === 'correta'));
    bWrong.setAttribute('aria-pressed', String(state.key === 'errada'));
    bCut.setAttribute('aria-pressed', String(state.cutaway));
    if (String(range.value) !== String(state.insert)) range.value = String(state.insert);
    range.setAttribute('aria-valuetext', state.insert + '%');
    range.disabled = !state.key;
    bRemove.disabled = !state.key;
    bRet.disabled = !rot;
    root.dataset.rotated = rot ? 'true' : 'false';
  }

  function settle() {
    if (state.angle !== state.target) state = transition(state, { type: 'tick', instant: true });
  }

  function frame(t) {
    raf = 0;
    const dt = last ? Math.min(0.05, (t - last) / 1000) : 0.016;
    last = t;
    state = transition(state, { type: 'tick', dt });
    draw(); ui();
    if (state.angle !== state.target) schedule();
  }

  function schedule() {
    if (raf) return;
    if (reduced || !visible) { settle(); draw(); ui(); return; }
    last = 0;
    raf = requestAnimationFrame(frame);
  }

  function act(a) {
    state = transition(state, a);
    if (reduced) settle();
    draw(); ui();
    if (state.angle !== state.target) schedule();
  }

  const on = (el, ev, fn) => el.addEventListener(ev, fn);
  on(bRight, 'click', () => act({ type: 'key', key: 'correta' }));
  on(bWrong, 'click', () => act({ type: 'key', key: 'errada' }));
  on(bRemove, 'click', () => act({ type: 'remove' }));
  on(range, 'input', () => act({ type: 'insert', value: range.value }));
  on(range, 'change', () => act({ type: 'insert', value: range.value }));
  on(bTurn, 'click', () => act({ type: 'turn' }));
  on(bRet, 'click', () => act({ type: 'return' }));
  on(bCut, 'click', () => act({ type: 'cutaway' }));
  on(bReset, 'click', () => { if (raf) { cancelAnimationFrame(raf); raf = 0; } act({ type: 'reset' }); });

  function onEnv(e) {
    const d = e.detail || {};
    if (d.theme) theme = d.theme === 'dark' ? 'dark' : 'light';
    if (typeof d.reducedMotion === 'boolean') reduced = d.reducedMotion;
    if (typeof d.visible === 'boolean') visible = d.visible;
    if ((reduced || !visible) && raf) { cancelAnimationFrame(raf); raf = 0; }
    if (reduced) settle();
    draw(); ui();
    if (state.angle !== state.target) schedule();
  }
  root.addEventListener('figure:environment', onEnv);

  draw(); ui();

  return () => {
    if (raf) cancelAnimationFrame(raf);
    raf = 0;
    root.removeEventListener('figure:environment', onEnv);
    root.innerHTML = '';
    root.classList.remove('fx-root');
  };
}

