    for (const [i, yy] of [17.6, 19.2, 20.8].entries()) o.push(L(k.lineOnTop([label.x + 1.4, yy + 1.0], [label.x + label.w - (i === 2 ? 3.4 : 1.4), yy + 1.0], BASE_TOP + 0.35, P), { tone: "lo", free: true }));
