      o.push(S(k.cylinder(x, y, 1.35, BASE_TOP + 0.9, -0.9 - BASE_TOP - 0.9, P, 20), { tone: "mid", crease: "none" }));
      o.push(S(k.cylinder(x, y, 2.2, -0.9, 0.9, P, 24), { tone: "mid" }));
