      const hatch = mHatch([[[R, z0], [TOWER, z0], [TOWER, z1], [R, z1]]], Math.PI / 4, 0.95, 0.2).map(([a, b]) => [[a[0], 0, a[1]], [b[0], 0, b[1]]]);
