    const cover = { x: TOWER, y: -TOWER_Y, w: 0.9, d: TOWER_Y, r: 0 };
    const cv = k.slabOf(cover, 1.0, ZTOP - 2.0, P, 1, 0);
    const scr = [[TOWER + 0.9, -2.0, 3.3], [TOWER + 0.9, -2.0, ZTOP - 3.3]];
    parts.cover = `<g class="lk-steel">${S(cv, { tone: "mid" })}${L(scr.map((p) => k.sideRing(p, 1.05, "x", P, 20)).join(""), { tone: "mid" })}${D(scr.map(at), { size: 0.55, tone: "mid" })}${L(scr.map((p) => k.segment([p[0], p[1] - 1.05, p[2]], [p[0], p[1] + 1.05, p[2]], P)).join(""), { tone: "mid" })}</g>`;
    // the shear line: where the plug meets the housing (the one lit accent)
    parts.shear = `<path class="iso-line lk-shear" d="${k.segment([R, 0, 0], [R, 0, ZTOP], P)}${k.segment([-R, 0, 0], [-R, 0, ZTOP], P)}"/>`;
    // clip: the openings through which the inside of the bore shows
    const rect = [[-R, 0, 0], [R, 0, 0], [R, 0, ZTOP], [-R, 0, ZTOP]].map(at);
    const topHole = mArc(0, 0, R, 0, -Math.PI, 40).map(([x, y]) => at([x, y, ZTOP]));
    parts.clip = `<clipPath id="lk-bore"><path d="${k.pathOf(rect, true)}"/><path d="${k.pathOf(topHole, true)}"/></clipPath>`;
  }
  // ---- drivers (built at x = 0, moved along x)
  parts.drivers = Z.map((z, n) => `<g data-driver="${n}" class="lk-driver">${mSvg(mItems(lkDriver(n), P)[0])}${L(lkPinRing(P, 0.4, z, PIN_R) + lkPinRing(P, LK.DRIVER - 0.4, z, PIN_R), { tone: "mid" })}</g>`).join("");
  return parts;
}

let staticKey="",staticScene;
export function render(state,options={}) {
  const ps=pose(state);
  const st={phi:state.angle*Math.PI/180,key:state.key==='correta'?1:0,
    ins:state.key?(1-state.insert/100)*LK.OUT:LK.OUT,lift:0,
    tips:ps.pins.map(p=>p.keyPin.z0),drivers:ps.pins.map(p=>p.driver.z0),
    fail:state.tone==='block'&&state.key==='errada'?1:0,alpha:state.key?1:0};
  st.bolt=LK.CAM_L*Math.sin(st.phi);
  const top=state.key?st.ins:0;
  const bounds=[...k.boxCorners(BASE,BASE_TOP-BASE_H-FOOT_H,BASE_TOP),
    [TOWER+1,-TOWER_Y,ZTOP],[-RH,0,ZTOP]];
  if(state.key)bounds.push(...[-12.5,10.6].flatMap(x=>[[x,0,FACE+top+24.6],[x,0,FACE+top+18]]));
  else bounds.push([-RH,0,FACE+2],[TOWER,0,FACE+2]);
  const W=720,H=720;
  const P=k.fitProjection(bounds,W,H,{pad:26,azimuth:120,elevation:30});
  const cacheKey=JSON.stringify(P);
  if(cacheKey!==staticKey){staticScene=scene(P);staticKey=cacheKey}
  const p=staticScene,f=lkFrame(P,st);
  const closed=state.cutaway?'':`<g class="lk-steel">${k.solidSvg(k.cylinder(0,0,RH,0,ZTOP,P,48),{tone:'mid'})}${k.solidSvg(k.slabOf({x:0,y:-TOWER_Y,w:TOWER,d:TOWER_Y*2,r:0.6},0,ZTOP,P,3,0.3),{tone:'mid'})}</g>`;
  const body=[`<defs>${p.clip}</defs>`,p.base,p.posts,p.guideBack,
    p.bolt.replace('data-part="bolt"',`data-part="bolt" transform="${f.bolt}"`),p.guideFront,p.keeper,
    `<g class="lk-cam">${f.cam}</g>`,p.housingA,
    `<g class="lk-spring-back"><path d="${f.springBack}"/></g>`,p.housingB,p.cover,
    `<g clip-path="url(#lk-bore)">${f.inside}</g>`,p.shear,f.outside,f.alert,
    p.drivers.replace(/data-driver="(\d)"/g,(m,n)=>`${m} transform="${f.drivers[+n]}"`),
    `<g class="lk-spring"><path class="lk-wire" d="${f.springFront}"/><path class="lk-wire-hi" d="${f.springFront}"/></g>`,`<g class="lk-key">${f.high}</g>`,closed].join('');
  const cls=state.key?'with-key':'without-key';
  return `<svg class="iso-svg" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" data-free="${ps.pins.every(p=>p.aligned)}" role="img" aria-label="Fechadura isométrica em corte com cinco pares de pinos. Giro ${Math.round(state.angle)} graus."><g class="${cls}">${body}</g></svg>`;
}
